    P_wpos  : rdn RSEGS mem' (Z_to_bv 64 0xf99d0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12bea0));
    P_wbase : rdn RSEGS mem' (Z_to_bv 64 0xf99e0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12bea0));
